-- Catálogos DIAN (mismos IDs que la API de facturación electrónica)
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS pc_dian_departamentos (id INT UNSIGNED NOT NULL PRIMARY KEY, country_id INT UNSIGNED NOT NULL, code VARCHAR(5) NOT NULL, name VARCHAR(100) NOT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pc_dian_municipios (id INT UNSIGNED NOT NULL PRIMARY KEY, country_id INT UNSIGNED NOT NULL, department_id INT UNSIGNED NOT NULL, code VARCHAR(10) NOT NULL, name VARCHAR(150) NOT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, KEY idx_dep (department_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DELETE FROM pc_dian_municipios; DELETE FROM pc_dian_departamentos;
